using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ScenarioRunner _scenarioRunner = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        var app = await appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.CreateHttpClient("chat") is not null
            ? app.Services.GetRequiredService<IChatClient>()
            : throw new InvalidOperationException("Chat client not available.");

        // Use the same chat client as the evaluator for quality metrics.
        _evaluatorClient = _chatClient;

        var reportingConfiguration = new ReportingConfiguration(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "evaluations"));

        _scenarioRunner = new ScenarioRunner(
            reportingConfiguration,
            getMetricEvaluators: () =>
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new GroundednessEvaluator()
            ],
            chatClient: _evaluatorClient);
    }

    [TestMethod]
    public async Task Greeting_Scenario()
    {
        await RunScenarioAsync(
            scenarioName: "greeting",
            userMessage: "Hello, how can you help me today?");
    }

    [TestMethod]
    public async Task FactualQuestion_Scenario()
    {
        await RunScenarioAsync(
            scenarioName: "factual_question",
            userMessage: "What is the capital of France?");
    }

    [TestMethod]
    public async Task MultiTurn_Scenario()
    {
        await _scenarioRunner.RunScenarioAsync(
            scenarioName: "multi_turn",
            async (turnContext) =>
            {
                var history = new List<ChatMessage>();

                history.Add(new ChatMessage(ChatRole.User, "My name is Alice."));
                var response1 = await _chatClient.GetResponseAsync(history);
                history.Add(new ChatMessage(ChatRole.Assistant, response1.Text));

                history.Add(new ChatMessage(ChatRole.User, "What is my name?"));
                var response2 = await _chatClient.GetResponseAsync(history);
                history.Add(new ChatMessage(ChatRole.Assistant, response2.Text));

                turnContext.RecordConversationHistory(history);
            });
    }

    private async Task RunScenarioAsync(string scenarioName, string userMessage)
    {
        await _scenarioRunner.RunScenarioAsync(
            scenarioName: scenarioName,
            async (turnContext) =>
            {
                var messages = new List<ChatMessage>
                {
                    new ChatMessage(ChatRole.User, userMessage)
                };

                var response = await _chatClient.GetResponseAsync(messages);
                messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));

                turnContext.RecordConversationHistory(messages);
            });
    }
}

